18	
19	import org.aspectj.lang.annotation.Aspect;
20	import org.aspectj.lang.annotation.Before;
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.samples.petclinic.repository.OwnerRepository;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Assigns a customerCode '<CITY3>-<LAST3>-<NNNN>' to each newly-created owner just before it is
27	 * saved: CITY3 and LAST3 are the upper-cased first three letters of the city and last name, and
28	 * NNNN is a per-city 4-digit sequence equal to one more than the owners already in that city. Kept
29	 * as its own small aspect so this rule stays a self-contained unit rather than growing the controller
30	 * or service.
31	 */
32	@Aspect
33	@Component
34	public class OwnerCustomerCodeAdvice {
35	
36	    private final OwnerRepository ownerRepository;
37	
38	    public OwnerCustomerCodeAdvice(OwnerRepository ownerRepository) {
39	        this.ownerRepository = ownerRepository;
40	    }
41	
42	    @Before("execution(* org.springframework.samples.petclinic.service.ClinicService.saveOwner(..)) && args(owner)")
43	    public void assignCustomerCode(Owner owner) {
44	        if (owner.isNew() && owner.getCustomerCode() == null) {
45	            String city3 = (owner.getCity() + "XXX").substring(0, 3).toUpperCase();
46	            String last3 = (owner.getLastName() + "XXX").substring(0, 3).toUpperCase();
47	            long inCity = ownerRepository.findAll().stream()
48	                .filter(o -> owner.getCity().equalsIgnoreCase(o.getCity())).count();
49	            owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, inCity + 1));
50	        }
51	    }
52	}
